\section{The finite-population framework}\label{sec:framework}

Throughout, $\iota$ is a finite index set of \emph{keys}, $|\iota| = n$.

\begin{definition}[Draw regime]
A \emph{draw regime} on $\iota$ is a vector $p = (p_i)_{i\in\iota}$ with $p_i \ge 0$ and
$\sum_i p_i = 1$. It is \emph{full-support} if $p_i > 0$ for all $i$. The \emph{uniform
regime} $p^{U}$ assigns $1/n$ to each key.
\end{definition}

\begin{definition}[Weighted moments]
For $f, g : \iota \to \mathbb{R}$ set
\[
\bar f = \sum_i p_i f_i,\qquad
\ip{f}{g} = \sum_i p_i f_i g_i,\qquad
\sigma_{fg} = \sum_i p_i (f_i - \bar f)(g_i - \bar g),
\]
and $\sigma_{ff} = \Var_p f$, $\|f\|^2 = \ip{f}{f}$.
\end{definition}

The inner product is symmetric, bilinear and positive semidefinite; in particular the weighted
Cauchy--Schwarz inequality $\ip{f}{g}^2 \le \|f\|^2\|g\|^2$ holds for every draw regime.

\begin{definition}[Variance share]
For $\sigma_{xx}, \sigma_{yy} > 0$,
$R^2(x,y) = \sigma_{xy}^2 / (\sigma_{xx}\sigma_{yy})$.
\end{definition}

\begin{definition}[Weighted error]
For $a,b\in\mathbb{R}$, $\MSE(a,b) = \sum_i p_i (y_i - a - b x_i)^2$.
\end{definition}

Two features are named once and for all: the \textbf{footprint} $x$ (the validated baseline
predictor, written $w$ in the numerical examples) and the candidate \textbf{feature} $z$ (the
prime-power indicator, written $\pp$).

\section{The gain functional and its exact algebra}\label{sec:gain}

\subsection{Residuals as certified optima}

\begin{definition}[Residual]
A function $r:\iota\to\mathbb{R}$ is a \emph{residual for $x$ under $p$} if it satisfies the
normal equations $\sum_i p_i r_i = 0$ and $\ip{r}{x} = 0$.
\end{definition}

\begin{theorem}[Optimality certificate]\label{thm:opt}
Suppose $y_i = a + b x_i + r_i$ for all $i$, where $r$ is a residual for $x$ under $p$. Then
$(a,b)$ is a global least-squares optimum: $\MSE(a,b) \le \MSE(a',b')$ for all $a', b'$.
\end{theorem}

\begin{proof}[Proof sketch]
With $\delta_i = (a-a') + (b-b')x_i$,
\[
\MSE(a',b') = \|r\|^2 + 2(a-a')\sum_i p_i r_i + 2(b-b')\ip{r}{x} + \sum_i p_i\delta_i^2 .
\]
The cross terms vanish by the normal equations and the last term is nonnegative.
\end{proof}

Theorem~\ref{thm:opt} makes ``the residual'' unambiguous: the normal equations certify
optimality simultaneously in every draw regime.

\subsection{The gain}

\begin{definition}[Augmentation gain]
For a residual $r$ and a feature $z$ with $\|z\|^2 > 0$,
$\gain(r,z) = \ip{r}{z}^2/\|z\|^2$.
\end{definition}

\begin{theorem}[Gain is the residual drop]\label{thm:drop}
With $c = \ip{r}{z}/\|z\|^2$,
$\sum_i p_i (r_i - c z_i)^2 = \|r\|^2 - \gain(r,z)$; in particular
$0 \le \gain(r,z) \le \|r\|^2$.
\end{theorem}

\begin{proof}[Proof sketch]
Expand the square and substitute the optimal coefficient; the cross and quadratic terms combine
to $-\ip{r}{z}^2/\|z\|^2$.
\end{proof}

\begin{proposition}[Exact vanishing]\label{prop:vanish}
If $\|z\|^2 > 0$ then $\gain(r,z) = 0$ if and only if $\ip{r}{z} = 0$.
\end{proposition}

\subsection{Collinearity annihilates the gain}

\begin{lemma}[Residual blindness]\label{lem:blind}
If $r$ is a residual for $x$, then $\ip{r}{a + bx + v} = \ip{r}{v}$ for all $a,b$ and all $v$.
\end{lemma}

\begin{corollary}[Perfect collinearity]
If $z_i = a + b x_i$ for all $i$, then $\gain(r,z) = 0$.
\end{corollary}

\begin{theorem}[Collinearity-defect ceiling]\label{thm:defect}
Let $r$ be a residual for $x$, $\|z\|^2 > 0$, and $a,b$ arbitrary. With $d_i = z_i - (a+bx_i)$,
\[
\gain(r,z) \;\le\; \|r\|^2\cdot\frac{\|d\|^2}{\|z\|^2}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:blind}, $\ip{r}{z} = \ip{r}{d}$; apply Cauchy--Schwarz and divide by
$\|z\|^2$.
\end{proof}

The minimum of $\|d\|^2/\|z\|^2$ over $(a,b)$ is the \emph{relative collinearity defect}. A
feature nearly affine in the footprint is provably nearly useless in every population.

\subsection{Gains are sequential, not additive}

\begin{theorem}[Sequential decomposition]\label{thm:seq}
Let $\|z\|^2, \|w\|^2 > 0$, $c = \ip{r}{z}/\|z\|^2$, $r' = r - cz$, $d = \ip{r'}{w}/\|w\|^2$.
Then
\[
\sum_i p_i (r'_i - d w_i)^2 = \|r\|^2 - \gain(r,z) - \gain(r',w).
\]
\end{theorem}

The second summand is the gain of $w$ against the \emph{adjusted} residual. This is the formal
reason a feature validated in isolation may evaporate inside a combined model.

\section{Partialling and the exact increment identity}\label{sec:partial}

\begin{definition}[Partialled feature]
$\tilde z$ is a \emph{partialling of $z$ against $x$ under $p$} if $\tilde z$ is a residual for
$x$ and $z_i = a + b x_i + \tilde z_i$ for some $a, b$ and all $i$.
\end{definition}

\begin{theorem}[Weighted Pythagoras]\label{thm:pyth}
If $\tilde z$ partials $z$, then $\|\tilde z\|^2 \le \|z\|^2$.
\end{theorem}

\begin{theorem}[Duality of partialling]\label{thm:dual}
Let $r$ be a residual for $x$ and $\tilde z$ a partialling of $z$. Then
$\ip{r}{z} = \ip{r}{\tilde z}$, and if $y = a' + b'x + r$ then also
$\ip{r}{z} = \ip{y}{\tilde z}$.
\end{theorem}

\begin{proof}[Proof sketch]
Both are Lemma~\ref{lem:blind} applied on the appropriate side: $r$ ignores the affine-in-$x$
part of $z$, and $\tilde z$ ignores the affine-in-$x$ part of $y$.
\end{proof}

\begin{definition}[Partialled gain]
$\pgain(r,\tilde z) = \ip{r}{\tilde z}^2/\|\tilde z\|^2 = \Delta R^2(z\mid x)\cdot\sigma_{yy}$.
\end{definition}

\begin{proposition}
If $\|\tilde z\|^2 > 0$ then $\gain(r,z) \le \pgain(r,\tilde z)$, and if also $\|z\|^2 > 0$ the
two vanish simultaneously.
\end{proposition}

\begin{theorem}[Unexplained share]\label{thm:unexp}
If $y = a + bx + r$ with $r$ a residual for $x$, and $\sigma_{xx},\sigma_{yy} > 0$, then
$1 - R^2(x,y) = \|r\|^2/\sigma_{yy}$.
\end{theorem}

\begin{proof}[Proof sketch]
From the decomposition, $\sigma_{xy} = b\sigma_{xx}$ and $\sigma_{yy} = b^2\sigma_{xx} +
\|r\|^2$, so $R^2 = b^2\sigma_{xx}/\sigma_{yy}$.
\end{proof}

\begin{theorem}[Exact increment identity]\label{thm:identity}
Under the hypotheses of Theorem~\ref{thm:unexp}, with $\|r\|^2 > 0$ and $\|\tilde z\|^2 > 0$,
\[
\Delta R^2(z\mid x) = \bigl(1 - R^2(x,y)\bigr)\cdot
\frac{\ip{r}{\tilde z}^2}{\|r\|^2\,\|\tilde z\|^2}
= \bigl(1 - R^2_{\mathrm{base}}\bigr)\cdot \rho_{\mathrm{partial}}^2 .
\]
\end{theorem}

The increment is the product of \emph{headroom} and \emph{partial correlation}; each factor can
move independently between populations, and a replicated baseline pins down only the first.

\section{Moment geometry: what the increment sees}\label{sec:moment}

\begin{theorem}[Partial covariance in moment form]\label{thm:pcov}
Let $\sum_i p_i = 1$, $y = a + bx + r$ with $r$ a residual for $x$, and $\sigma_{xx} > 0$. Then
for any feature $z$,
\[
\ip{r}{z} = \sigma_{zy} - \frac{\sigma_{xy}\sigma_{xz}}{\sigma_{xx}} .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Since $r$ is centred, $\ip{r}{z} = \sigma_{rz}$. Covarying $y = (a+bx) + r$ with $z$ gives
$\sigma_{zy} = b\sigma_{xz} + \sigma_{rz}$, and $\sigma_{xy} = b\sigma_{xx}$ eliminates $b$.
\end{proof}

\begin{theorem}[Partialled energy in moment form]\label{thm:pvar}
If $\tilde z$ partials $z$ against $x$ and $\sigma_{xx} > 0$, then
$\|\tilde z\|^2 = \sigma_{zz} - \sigma_{xz}^2/\sigma_{xx}$.
\end{theorem}

\begin{theorem}[Moment formula for the increment]\label{thm:momform}
Under the hypotheses above,
\[
\pgain(r,\tilde z)
= \frac{\bigl(\sigma_{zy} - \sigma_{xy}\sigma_{xz}/\sigma_{xx}\bigr)^2}
{\sigma_{zz} - \sigma_{xz}^2/\sigma_{xx}},
\qquad
\Delta R^2(z\mid x)
= \frac{\bigl(\sigma_{zy}\sigma_{xx} - \sigma_{xy}\sigma_{xz}\bigr)^2}
{\sigma_{xx}\bigl(\sigma_{zz}\sigma_{xx} - \sigma_{xz}^2\bigr)\sigma_{yy}} .
\]
\end{theorem}

\begin{theorem}[Moment sufficiency]\label{thm:suff}
Let $(\iota,p,x,y,z)$ and $(\kappa,q,x',y',z')$ be two populations on possibly different finite
key sets with possibly different draw regimes, each satisfying the hypotheses of
Theorem~\ref{thm:momform}. If
\[
\sigma_{xx} = \sigma'_{x'x'},\quad \sigma_{xy} = \sigma'_{x'y'},\quad
\sigma_{xz} = \sigma'_{x'z'},\quad \sigma_{zy} = \sigma'_{z'y'},\quad
\sigma_{zz} = \sigma'_{z'z'},
\]
then $\pgain(r,\tilde z) = \pgain(r',\tilde z')$.
\end{theorem}

Two corollaries deserve emphasis. \emph{Higher-order effects are exonerated}: nothing about
third or higher moments, support size, sampling seed, or tail behaviour can change the
increment while the five moments are fixed, so a non-replication must be visible as a change in
$(\sigma_{xx},\sigma_{xy},\sigma_{xz},\sigma_{zy},\sigma_{zz})$. \emph{The diagnostic burden is
finite}: five numbers suffice, and two of them---$\sigma_{xz}$ and $\sigma_{zy}$---are typically
not reported alongside the marginal dials.

\begin{theorem}[Absence locus]\label{thm:quadric}
Under the hypotheses of Theorem~\ref{thm:momform}, with $\|\tilde z\|^2 > 0$,
\[
\Delta R^2(z\mid x) = 0 \iff \sigma_{zy}\,\sigma_{xx} = \sigma_{xy}\,\sigma_{xz} .
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Proposition~\ref{prop:vanish} and Theorem~\ref{thm:dual} the increment vanishes iff
$\ip{r}{\tilde z} = 0$; apply Theorem~\ref{thm:pcov} and clear the positive denominator.
\end{proof}

The absence locus is a genuine quadric in moment space, with an exact interpretation: the
feature's covariance with the rate is precisely what the footprint predicts from the
footprint--feature overlap.

\section{Absence is a codimension-one coincidence}\label{sec:codim}

Fix $(\iota, p)$, a footprint $x$ and a nondegenerate partialled feature $\tilde z$, and let the
rate profile $y$ range over $\mathbb{R}^{n}$.

\begin{definition}[Zero-gain functional]
$\Lambda:\mathbb{R}^{\iota}\to\mathbb{R}$, $\Lambda(y) = \ip{y}{\tilde z}$; this map is linear.
\end{definition}

\begin{theorem}[Kernel characterisation]
For $y = a' + b'x + r$ with $r$ a residual for $x$ and $\|\tilde z\|^2 > 0$,
$y \in \ker\Lambda$ if and only if $\Delta R^2(z\mid x) = 0$.
\end{theorem}

\begin{theorem}[Codimension one]\label{thm:codim}
If $\|\tilde z\|^2 \ne 0$ then $\Lambda$ is surjective and $\dim\ker\Lambda + 1 = n$.
\end{theorem}

\begin{proof}[Proof sketch]
$\Lambda\bigl((t/\|\tilde z\|^2)\tilde z\bigr) = t$ for every $t$, so $\Lambda$ is onto; apply
rank--nullity in $\mathbb{R}^{\iota}$.
\end{proof}

In a single population the set of rate profiles on which the feature is exactly absent is a
hyperplane, hence of measure zero. Absence is a knife edge: seeing it once is surprising,
seeing it on five independently drawn fresh populations indicates a mechanism.

\section{Two explicit populations}\label{sec:examples}

Both examples use four keys under the uniform regime $p^{U} = (1/4,1/4,1/4,1/4)$ with the
prime-power indicator $\pp = (1,1,0,0)$.

\subsection{The non-replication pair}

Take the footprint $w = (1,2,3,4)$ and the rate profiles
\[
y^{A} = \left(\tfrac{12}{7}, \tfrac{3}{7}, 4, \tfrac{27}{7}\right),\qquad
y^{B} = (2,1,2,5),
\]
with least-squares decompositions $y = 0 + 1\cdot w + r$ and residuals
$r^{A} = \left(\tfrac57, -\tfrac{11}{7}, 1, -\tfrac17\right)$, $r^{B} = (1,-1,-1,1)$, both
satisfying the normal equations and hence certified by Theorem~\ref{thm:opt}. The partialling of
$\pp$ against $w$ is $\pp = \tfrac32 - \tfrac25 w + \widetilde{\pp}$ with
$\widetilde{\pp} = \left(-\tfrac1{10}, \tfrac3{10}, -\tfrac3{10}, \tfrac1{10}\right)$ and
$\|\widetilde{\pp}\|^2 = 1/20 > 0$.

\begin{theorem}[Non-replication]\label{thm:nonrep}
$R^2(w,y^{A}) = R^2(w,y^{B}) = \tfrac59$, $\sigma_{y^{A}y^{A}} = \sigma_{y^{B}y^{B}} = \tfrac94$
and $\|r^{A}\|^2 = \|r^{B}\|^2 = 1$, yet
\[
\Delta R^2(\pp) = \tfrac{20}{49} \approx 0.408 \text{ on } A,
\qquad \Delta R^2(\pp) = 0 \text{ on } B .
\]
For the cruder raw gain the readings are $2/49 \approx 0.041$ and $0$.
\end{theorem}

\begin{proof}[Proof sketch]
Direct evaluation: $\ip{r^{A}}{\widetilde{\pp}} = -3/14$, so
$\pgain = (3/14)^2/(1/20) = 45/49$ and $\Delta R^2 = (45/49)/(9/4) = 20/49$, while
$\ip{r^{B}}{\widetilde{\pp}} = 0$ exactly.
\end{proof}

\subsection{Sign masking: every marginal reading identical}

Keep $w$ and $\pp$, and take
\[
y^{\mathrm{sup}} = \left(\tfrac7{10}, -\tfrac25, -\tfrac3{10}, 1\right),\qquad
y^{\mathrm{act}} = \left(\tfrac3{10}, \tfrac25, -\tfrac7{10}, 1\right),
\]
with least-squares decompositions $y = 0 + \tfrac1{10}w + r$ and residuals
$r^{\mathrm{sup}} = \left(\tfrac35,-\tfrac35,-\tfrac35,\tfrac35\right)$,
$r^{\mathrm{act}} = \left(\tfrac15,\tfrac15,-1,\tfrac35\right)$.

\begin{theorem}[Sign-masking non-replication]\label{thm:mask}
Both populations satisfy $R^2(w,y) = \tfrac{5}{149}$, $R^2(\pp,y) = \tfrac{4}{149}$ and
$\sigma_{yy} = \tfrac{149}{400}$, and they share the footprint--feature overlap $\sigma_{xz}$.
They differ only in the sign of the feature--rate covariance,
$\sigma_{zy}^{\mathrm{sup}} = -\tfrac1{20} = -\sigma_{zy}^{\mathrm{act}}$. Their increments are
\[
\Delta R^2(\pp) = 0 \quad\text{(suppressed)},\qquad
\Delta R^2(\pp) = \tfrac{80}{149}\approx 0.537 \quad\text{(active)} .
\]
Moreover the suppressed population lies exactly on the absence quadric
$\sigma_{zy}\sigma_{xx} = \sigma_{xy}\sigma_{xz}$ and the active one does not.
\end{theorem}

\begin{proof}[Proof sketch]
All quantities are four-term rational sums; the profiles are constructed so that the centred
vectors have equal norms and equal projections onto $w$ and onto $\pp$ up to sign. For the
increments, $\ip{r^{\mathrm{sup}}}{\widetilde{\pp}} = 0$ while
$\ip{r^{\mathrm{act}}}{\widetilde{\pp}}^2/\|\widetilde{\pp}\|^2 = 1/5$, and
$(1/5)/(149/400) = 80/149$.
\end{proof}

\begin{remark}
Every marginal diagnostic an augmented-dial experiment records---base dial, marginal feature
dial, rate variance, feature--footprint overlap---is numerically identical on a population where
the feature contributes more than half the variance and on one where it contributes nothing. The
mechanism is \emph{suppression}, and only the signed discriminant
$\sigma_{zy}\sigma_{xx} - \sigma_{xy}\sigma_{xz}$ detects it. Stable marginals are not weak
evidence for a replicable increment; they are no evidence.
\end{remark}

\subsection{Marginal signal without incremental signal}

\begin{definition}[Comonotone]
$z$ and $y$ are \emph{comonotone} if $(z_i - z_j)(y_i - y_j)\ge 0$ for all $i,j$.
\end{definition}

Comonotone, non-constant pairs have strictly positive covariance under every full-support draw
regime---the strongest regime-invariant marginal signal available.

\begin{theorem}[Marginal present, incremental absent]\label{thm:marginal}
Let $w' = \left(\tfrac72,\tfrac72,1,0\right)$ and $y' = (4,3,1,0)$, with $y' = 0 + 1\cdot w' + r'$,
$r' = \left(\tfrac12,-\tfrac12,0,0\right)$. Then
\begin{enumerate}
\item $\pp$ and $y'$ are comonotone, hence $\sigma_{\pp y'} > 0$ in \emph{every} full-support
draw regime;
\item the baseline is not saturated: $R^2(w',y') = \tfrac{19}{20}$ and $\|r'\|^2 = \tfrac18 > 0$;
\item nevertheless $\Delta R^2(\pp\mid w') = 0$ exactly.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
(1) is a finite check over ordered pairs plus positivity of covariance for comonotone pairs;
(2) is direct evaluation; for (3) the partialling is
$\widetilde{\pp}' = \tfrac1{38}(1,1,-7,5)$ and $\ip{r'}{\widetilde{\pp}'} = 0$ because $r'$ is
supported on the first two keys with opposite signs while $\widetilde{\pp}'$ is constant there.
\end{proof}

\section{Two ceilings: collinearity and sparsity}\label{sec:ceilings}

Theorem~\ref{thm:defect} gives one structural ceiling. The second needs no cancellation at all.

\begin{theorem}[Sparse-indicator ceiling]\label{thm:sparse}
Let $z$ be a $0/1$ feature with draw-regime density $\delta = \sum_i p_i z_i > 0$, and let
$|r_i| \le B$ for all $i$. Then $\gain(r,z) \le B^2\delta$.
\end{theorem}

\begin{proof}[Proof sketch]
For a $0/1$ feature $\|z\|^2 = \delta$; and
$|\ip{r}{z}| \le \sum_i p_i|r_i| z_i \le B\delta$, so $\gain \le B^2\delta^2/\delta$.
\end{proof}

\begin{corollary}
If $B>0$ and $\delta < \varepsilon/B^2$ then $\gain(r,z) < \varepsilon$, uniformly over all
residuals bounded by $B$ and all correlation structures.
\end{corollary}

\paragraph{Application to prime powers.} On $\{1,\dots,N\}$ the prime-power indicator is sparse:
every prime power exceeding $3$ is $\equiv \pm1 \pmod 6$, capping the density near $1/3$, and the
true density $\delta_N$ tends to $0$. Hence the raw prime-power gain is at most $B^2\delta_N \to
0$ under bounded residuals. Whatever produced $+0.089$ on one small key range cannot survive to
large key ranges---a mechanism for absence requiring only counting.

\section{Exonerating the usual suspects}\label{sec:exonerate}

\begin{theorem}[Total-variation stability]\label{thm:tv}
If $|r_i z_i| \le M$ for all $i$, then for any draw regimes $p,q$,
$\bigl|\ip{r}{z}_p - \ip{r}{z}_q\bigr| \le M\sum_i |p_i - q_i|$.
\end{theorem}

\begin{corollary}[Drift cannot resurrect an absent feature]
If $\ip{r}{z}_q = 0$ for some regime $q$, then for every regime $p$ with $\|z\|_p^2 > 0$,
\[
\gain_p(r,z) \le \frac{\bigl(M\sum_i|p_i-q_i|\bigr)^2}{\|z\|_p^2}.
\]
\end{corollary}

The gain at a nearby regime is quadratically small in the regime distance: re-weighting a
population cannot manufacture an increment, only changing the population can.

\begin{theorem}[Slope attenuation]\label{thm:atten}
Suppose the measured footprint is $x + u$ with $\sigma_{xu} = 0$, $\sigma_{uy} = 0$, and the rate
calibrated on the true footprint, $\sigma_{xy} = \sigma_{xx}$. Then the fitted transfer slope is
\[
\frac{\sigma_{x+u,\,y}}{\sigma_{x+u,\,x+u}} = \frac{\sigma_{xx}}{\sigma_{xx} + \sigma_{uu}} .
\]
\end{theorem}

\begin{corollary}[Slope band]
If $0 < \sigma_{uu} \le \sigma_{xx}/5$ then the slope lies in $[5/6, 1)$.
\end{corollary}

A slope strictly below one is forced by measurement noise, and the observed $0.898$ sits inside
the band predicted by a noise-to-signal ratio of at most $1/5$.

\section{Back to the data}\label{sec:data}

The five recorded augmented-dial readings are
\[
\left(\tfrac{49}{100},\tfrac{111}{200},\tfrac{107}{250},\tfrac{133}{250},\tfrac{127}{250}\right)
= (0.490, 0.555, 0.428, 0.532, 0.508),
\]
with mean $2513/5000 = 0.5026 < 0.55$ and exactly one reading at or above the target.

\begin{theorem}[Falsification bound]\label{thm:tail}
If each fresh population independently clears the target with probability $q \ge 4/5$, then
\[
\Pr[\text{at most one success in five}] = (1-q)^5 + 5q(1-q)^4 \le \frac{21}{3125} < 0.007 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
The left side equals $5(1-q)^4 - 4(1-q)^5$, which is increasing in $1-q$ on $[0,1/5]$; evaluate
at $1-q = 1/5$.
\end{proof}

Observing exactly one success rejects the $80\%$-replication hypothesis at that level. Combined
with the structural results, the correct reading is: the augmented dial's target is not met, the
failure is attributable to the prime-power ingredient, and the mechanism lies in the second
moments---not in sampling variability. The transfer slope remains in band, and a combined model
reaching $R^2 = 0.634$ at its operating point is unaffected, since the prime-power ingredient
contributes nothing to it.

\section{Discussion}\label{sec:discussion}

\subsection{Increments are a different species of statistic}

\begin{center}
\begin{tabular}{@{}lll@{}}
\toprule
statistic & stability & geometry \\
\midrule
marginal covariance $\sigma_{zy}$ & robust (sign invariant if comonotone) & open half-space \\
base variance share $R^2(x,y)$ & robust & smooth in the moments \\
transfer slope & forced into a band by noise & monotone in noise-to-signal \\
\textbf{increment $\Delta R^2(z\mid x)$} & \textbf{knife-edge} &
\textbf{quadric; codimension-one zero set} \\
\bottomrule
\end{tabular}
\end{center}

Marginal statistics are open conditions; increments vanish on closed measure-zero sets. There is
no implication from the stability of the former to the stability of the latter, and
Theorem~\ref{thm:mask} shows the implication fails in the strongest possible way.

\subsection{What should be reported}

Theorem~\ref{thm:suff} turns this into practice. An augmented-dial report should carry the five
sufficient moments, or equivalently the two quantities the marginals omit: the \emph{overlap}
$\sigma_{xz}$ and the \emph{signed absence discriminant}
\[
D = \sigma_{zy}\sigma_{xx} - \sigma_{xy}\sigma_{xz},
\qquad
\Delta R^2 = \frac{D^2}{\sigma_{xx}(\sigma_{zz}\sigma_{xx} - \sigma_{xz}^2)\sigma_{yy}} .
\]
$D$ is the only quantity whose sign and magnitude distinguish suppression from contribution.
Reporting $D$ with its uncertainty converts a knife-edge statistic into a readable one: a
population near the absence quadric announces itself as $D \approx 0$, and the prediction that a
fresh population will report an absent increment becomes falsifiable in advance.

\subsection{Relation to the classical picture}

Theorem~\ref{thm:identity} is the finite-population, arbitrary-draw-regime form of the classical
identity relating a multiple-correlation increment to a squared partial correlation;
Theorems~\ref{thm:pcov}--\ref{thm:momform} are the corresponding closed forms in the
two-predictor case, and Theorem~\ref{thm:quadric} is the familiar suppression condition. What is
new is the use to which they are put: an exact codimension count, a sufficiency theorem across
heterogeneous populations, a construction with an invariant vector of marginal diagnostics and a
non-invariant increment, and a sparsity ceiling converting a number-theoretic density statement
directly into a bound on explanatory power.

\section{Algorithms}\label{sec:algorithms}

\paragraph{A. Certified augmentation audit.} Given $(p,x,z,y)$: compute the weighted moments in
$O(n)$; form $b = \sigma_{xy}/\sigma_{xx}$, $a = \bar y - b\bar x$; form $r$ and verify the
normal equations to certify optimality; partial $z$ against $x$; report
$\pgain = \ip{r}{\tilde z}^2/\|\tilde z\|^2$ and $\Delta R^2 = \pgain/\sigma_{yy}$. Cost $O(n)$.

\paragraph{B. Absence discriminant.} Given the five moments, compute $D$ and $\Delta R^2$ as
above; the population is on the absence locus exactly when $D = 0$. Cost $O(1)$ after an $O(n)$
moment pass. This is the recommended reporting statistic.

\paragraph{C. Sequential augmentation with ceilings.} Given candidates $z_1,\dots,z_m$: partial
each against the current model, compute each partialled gain, take the largest, update the
residual, repeat. At each step the collinearity-defect ceiling and, for $0/1$ features, the
sparsity ceiling $B^2\delta$ prune candidates before their gains are computed. Cost $O(mn)$ per
round.

\section{Future directions}\label{sec:future}

Three research cycles were run on the negative result ``the prime-power feature's contribution
does not replicate''. What survived scrutiny: absence is exact, not noisy (it occurs precisely
at residual orthogonality, i.e.\ on the quadric
$\sigma_{zy}\sigma_{xx} = \sigma_{xy}\sigma_{xz}$); absence is a codimension-one condition on
rate profiles, so seeing it once is a knife edge and seeing it five times is structure; marginal
stability implies nothing about increments; regime drift is exonerated while moment differences
are indicted; and sparsity is a sufficient mechanism.

\begin{conjecture}[Prime-power density ceiling]
For every $N$ and every residual bounded by $B$, the raw prime-power gain on $\{1,\dots,N\}$
under any draw regime whose mass on prime powers is $\delta_N$ satisfies $\gain \le B^2\delta_N$,
with $\delta_N \to 0$; hence the reported $+0.089$ cannot survive to large key ranges under
bounded residuals.
\end{conjecture}

The general ceiling is already proved; what remains is the number-theoretic input
$\#\{n\le N : n \text{ a prime power}\} = o(N)$, reachable by an elementary sieve---all prime
powers above $3$ are $\equiv\pm1\pmod 6$, giving $\delta_N \le 1/3 + o(1)$ immediately, with the
full $o(1)$ following from a Mertens-type product.

\begin{conjecture}[Suppression geometry of feature families]
For a generic footprint, the set of populations on which all features of a fixed family
$z_1,\dots,z_m$ are simultaneously absent has codimension exactly $m$ in moment space, and the
sequential-gain decomposition makes the codimension count additive.
\end{conjecture}

The case $m=1$ is complete; extending it needs the Gram matrix of the partialled family and its
rank. Further questions: whether the absence discriminant $D$, estimated on a pilot population
with an explicit error bar, yields a calibrated prediction interval for the increment on a fresh
population; which $0/1$ features of a given density maximise the worst-case increment over
populations with prescribed base dial; and whether replacing ``affine in $x$'' by ``in the span
of a fixed subspace'' turns the absence locus into a determinantal variety, as the projection
form of the argument suggests.

\section{Conclusion}

An increment is not a measurement of the same kind as a marginal association. It is a difference
of fits, and differences live on knife edges. We proved that the increment of a variance share is
a rational function of five second moments, that it vanishes exactly on a quadric in those
moments, that its zero set in rate-profile space is a hyperplane of codimension one, and that it
can be moved from $0$ to more than half the variance while every marginal diagnostic in a
standard report stays numerically fixed. Two independent mechanisms---suppression and
sparsity---suffice to produce absence with no appeal to noise, and two popular alternative
explanations, regime drift and slope decay, are ruled out quantitatively.

The prime-power feature's contribution did not replicate because, on the fresh populations, the
footprint had already accounted for everything the feature had to say. That is a statement about
second moments, it is exactly checkable, and it is the statistic that such experiments should
report.

