"""Algorithm B: absence discriminant and knife-edge sweep."""

from __future__ import annotations

from typing import List, Sequence, Tuple

Vec = Sequence[float]


def increment_from_moments(
    sxx: float, sxy: float, sxz: float, szy: float, szz: float, syy: float
) -> float:
    """Delta R^2 as a rational function of the six second moments.

    Only five of them enter the numerator/denominator structure; sigma_yy is the
    normalisation.  Requires sxx > 0 and szz*sxx - sxz^2 > 0 (feature not collinear
    with the footprint).
    """
    disc = szy * sxx - sxy * sxz
    return disc * disc / (sxx * (szz * sxx - sxz * sxz) * syy)


def absence_discriminant(
    sxx: float, sxy: float, sxz: float, szy: float
) -> float:
    """D = sigma_zy sigma_xx - sigma_xy sigma_xz.  Zero exactly on the absence quadric."""
    return szy * sxx - sxy * sxz


def moments(p: Vec, x: Vec, z: Vec, y: Vec) -> Tuple[float, float, float, float, float, float]:
    """The six weighted second moments (sxx, sxy, sxz, szy, szz, syy)."""

    def wmean(f: Vec) -> float:
        return sum(pi * fi for pi, fi in zip(p, f))

    def wcov(f: Vec, g: Vec) -> float:
        mf, mg = wmean(f), wmean(g)
        return sum(pi * (fi - mf) * (gi - mg) for pi, fi, gi in zip(p, f, g))

    return wcov(x, x), wcov(x, y), wcov(x, z), wcov(z, y), wcov(z, z), wcov(y, y)


def knife_edge_sweep(
    p: Vec, x: Vec, z: Vec, y: Vec, lo: float = -1.0, hi: float = 1.0, steps: int = 21
) -> List[Tuple[float, float, float]]:
    """Move the rate profile along the direction that changes only sigma_zy.

    The perturbation direction is the partialled feature z~ itself: adding t*z~ to y
    leaves sigma_xx, sigma_xz and sigma_zz untouched, leaves sigma_xy untouched (since
    z~ is x-orthogonal), and moves sigma_zy linearly.  The resulting increment is a
    parabola in t whose unique zero is the absence hyperplane crossing.

    Returns a list of (t, discriminant, increment).
    """

    def wmean(f: Vec) -> float:
        return sum(pi * fi for pi, fi in zip(p, f))

    def wcov(f: Vec, g: Vec) -> float:
        mf, mg = wmean(f), wmean(g)
        return sum(pi * (fi - mf) * (gi - mg) for pi, fi, gi in zip(p, f, g))

    b = wcov(x, z) / wcov(x, x)
    a = wmean(z) - b * wmean(x)
    zt = [zi - (a + b * xi) for xi, zi in zip(x, z)]

    out: List[Tuple[float, float, float]] = []
    for k in range(steps):
        t = lo + (hi - lo) * k / (steps - 1)
        yt = [yi + t * zti for yi, zti in zip(y, zt)]
        sxx, sxy, sxz, szy, szz, syy = moments(p, x, z, yt)
        out.append(
            (t, absence_discriminant(sxx, sxy, sxz, szy),
             increment_from_moments(sxx, sxy, sxz, szy, szz, syy))
        )
    return out


if __name__ == "__main__":
    p = [0.25] * 4
    w = [1.0, 2.0, 3.0, 4.0]
    pp = [1.0, 1.0, 0.0, 0.0]
    y = [0.7, -0.4, -0.3, 1.0]          # the suppressed population: D = 0
    print(f"{'t':>7}{'discriminant D':>18}{'Delta R^2':>14}")
    for t, d, inc in knife_edge_sweep(p, w, pp, y, -1.0, 1.0, 11):
        print(f"{t:>7.2f}{d:>18.6f}{inc:>14.6f}")
    print("\nThe increment touches zero exactly where D changes sign:")
    print("absence is a single point on this line — a hyperplane in profile space.")
